TRANSLIT = {
    "а": "a", "б": "b", "в": "v", "г": "g", "д": "d", "е": "e", "ё": "e", "ж": "zh",
    "з": "z", "и": "i", "й": "y", "к": "k", "л": "l", "м": "m", "н": "n", "о": "o",
    "п": "p", "р": "r", "с": "s", "т": "t", "у": "u", "ф": "f", "х": "h", "ц": "c",
    "ч": "ch", "ш": "sh", "щ": "sch", "ъ": "", "ы": "y", "ь": "", "э": "e",
    "ю": "yu", "я": "ya",
}


def plural(n: int, one: str, few: str, many: str) -> str:
    """Русское согласование числительного: 1 термин, 2 термина, 5 терминов."""
    r = abs(n) % 100
    if 11 <= r <= 14:
        return many
    r %= 10
    return one if r == 1 else few if 2 <= r <= 4 else many


def slug(term: str) -> str:
    """Якорь для термина: латиница в нижнем регистре, слова через дефис."""
    out = "".join(TRANSLIT.get(c, c) for c in term.lower())
    out = re.sub(r"[^a-z0-9]+", "-", out).strip("-")
    return out or "term"


def slug_map() -> dict[str, str]:
    """Ключ подсказки (русский и английский вариант) в якорь на странице глоссария."""
    seen: dict[str, int] = {}
    result: dict[str, str] = {}
    for term, en, _ch, _d in TERMS:
        s = slug(term)
        if s in seen:
            seen[s] += 1
            s = f"{s}-{seen[s]}"
        else:
            seen[s] = 1
        result[term.lower()] = s
        if en.lower() != term.lower():
            result.setdefault(en.lower(), s)
    return result


def main() -> None:
    js_map = {}
    for term, en, ch, definition in TERMS:
        js_map[term.lower()] = f"{definition} (глава {ch})"
        if en.lower() != term.lower():
            js_map[en.lower()] = f"{definition} (глава {ch})"

    slugs = slug_map()
    js = ("window.GLOSSARY = " + json.dumps(js_map, ensure_ascii=False, indent=1) + ";\n"
          + "window.GLOSSARY_SLUG = " + json.dumps(slugs, ensure_ascii=False, indent=1) + ";\n")
    (ROOT / "site" / "assets" / "glossary.js").write_text(js, encoding="utf-8")

    by_letter: dict[str, list] = {}
    for item in sorted(TERMS, key=lambda t: t[0].lower()):
        by_letter.setdefault(item[0][0].upper(), []).append(item)

    rows = []
    for letter in sorted(by_letter):
        rows.append(f'<h2 id="l-{letter}">{letter}</h2>\n<dl>')
        for term, en, ch, definition in by_letter[letter]:
            rows.append(
                f'<div class="gloss-item" id="t-{slugs[term.lower()]}">'
                f'<dt>{term} <span class="en">{en}</span></dt>'
                f'<dd>{definition}<span class="where">Вводится в главе '
                f'<a href="ch{int(ch):02d}.html">{ch}</a></span></dd></div>'
            )
        rows.append("</dl>")

    nav = " · ".join(f'<a href="#l-{l}">{l}</a>' for l in sorted(by_letter))

    page = (ROOT / "tools" / "app_a_template.html").read_text(encoding="utf-8")
    page = page.replace("{{COUNT}} терминов", f"{len(TERMS)} {plural(len(TERMS), 'термин', 'термина', 'терминов')}")
    page = page.replace("{{COUNT}}", str(len(TERMS)))
    page = page.replace("{{NAV}}", nav)
    page = page.replace("{{BODY}}", "\n".join(rows))
    (ROOT / "site" / "app-a.html").write_text(page, encoding="utf-8")

    print(f"глоссарий: {len(TERMS)} терминов, {len(js_map)} ключей для подсказок")


if __name__ == "__main__":
    main()
